data class Version(val effective: LocalDate, val terms: Terms)     // immutable version

class Contract(private val history: List<Version>) {                // continuity
    fun asOf(on: LocalDate): Terms? {
        val i = history.binarySearchBy(on) { it.effective }
        val idx = if (i >= 0) i else -i - 2        // predecessor of the insertion point
        return history.getOrNull(idx)?.terms       // null = before the first version
    }
    fun amend(effective: LocalDate, working: Terms): Contract =
        Contract((history + Version(effective, working)).sortedBy { it.effective })
}
